_CDP_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _cdp_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        if open_paren and word in CDP_METHODS:
            return "." + CDP_METHODS[word] + open_paren
        if word in CDP_PROPS:
            return "." + CDP_PROPS[word]
        return match.group(0)
    if word in CDP_CONSTS:
        return CDP_CONSTS[word]
    if word in CDP_FUNCS:
        return CDP_FUNCS[word] + (open_paren or "")
    return match.group(0)


def CDP_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _CDP_TOKEN.sub(_cdp_replace, text)
